import unittest

from ratings import average_rating, stars


class TestStars(unittest.TestCase):
    def test_a_rating_rounds_to_stars(self):
        self.assertEqual(stars(3.6), '****')

    def test_the_average_of_two_ratings(self):
        self.assertEqual(average_rating([4, 5]), 4.5)
